pub fn mint<'a>(
    token_program_id: AccountInfo<'a>,
    mint_account: AccountInfo<'a>,
    destination_account: AccountInfo<'a>,
    authority_account: AccountInfo<'a>,
    amount: u64,
    pool_pub_key: &Pubkey,
    bump_seed: u8,
) -> ProgramResult {
    let me_bytes = pool_pub_key.to_bytes();
    let authority_signature_seeds = [&me_bytes[..32], &[bump_seed]];
    let signers = &[&authority_signature_seeds[..]];

    let ix = spl_token::instruction::mint_to(
        token_program_id.key,
        mint_account.key,
        destination_account.key,
        authority_account.key,
        &[authority_account.key],
        amount,
    )?;

    invoke_signed(
        &ix,
        &[token_program_id, mint_account, destination_account, authority_account],
        signers,
    )
}

fn process_propose(program_id: &Pubkey, accounts: &[AccountInfo],
    tokens_to_mint: u64, acceptance_criteria: AcceptanceCriteria,
    mint_bump: u8, feature_id_bump: u8,
) -> ProgramResult {
    let mint_address = Pubkey::create_program_address(
        &[&feature_proposal_info.key.to_bytes(), br"mint", &[mint_bump]],
        program_id,
    )?;
    if mint_address != *mint_info.key {
        return Err(ProgramError::InvalidArgument);
    }

    let feature_id_address = Pubkey::create_program_address(
        &[&feature_proposal_info.key.to_bytes(), br"feature-id", &[feature_id_bump]],
        program_id,
    )?;
    if feature_id_address != *feature_id_info.key {
        return Err(ProgramError::InvalidArgument);
    }
    Ok(())
}

