pub fn process_transfer(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    amount: u64,
    expected_decimals: Option<u8>,
) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let source_account_info = next_account_info(account_info_iter)?;
    let expected_mint_info = if let Some(expected_decimals) = expected_decimals {
        Some((next_account_info(account_info_iter)?, expected_decimals))
    } else {
        None
    };
    let destination_account_info = next_account_info(account_info_iter)?;
    let authority_info = next_account_info(account_info_iter)?;

    let mut source_account = Account::unpack(&source_account_info.data.borrow())?;
    let mut destination_account = Account::unpack(&destination_account_info.data.borrow())?;

    if source_account.is_frozen() || destination_account.is_frozen() {
        return Err(TokenError::AccountFrozen.into());
    }
    if source_account.amount < amount {
        return Err(TokenError::InsufficientFunds.into());
    }
    if !Self::cmp_pubkeys(&source_account.mint, &destination_account.mint) {
        return Err(TokenError::MintMismatch.into());
    }

    match source_account.delegate {
        COption::Some(ref delegate) if Self::cmp_pubkeys(authority_info.key, delegate) => {
            Self::validate_owner(program_id, delegate, authority_info, account_info_iter.as_slice())?;
            if source_account.delegated_amount < amount {
                return Err(TokenError::InsufficientFunds.into());
            }
            source_account.delegated_amount = source_account.delegated_amount
                .checked_sub(amount).ok_or(TokenError::Overflow)?;
        }
        _ => Self::validate_owner(program_id, &source_account.owner, authority_info, account_info_iter.as_slice())?,
    };

    source_account.amount = source_account.amount.checked_sub(amount).ok_or(TokenError::Overflow)?;
    destination_account.amount = destination_account.amount.checked_add(amount).ok_or(TokenError::Overflow)?;

    Account::pack(source_account, &mut source_account_info.data.borrow_mut())?;
    Account::pack(destination_account, &mut destination_account_info.data.borrow_mut())?;
    Ok(())
}

pub fn process_decide(
    _program_id: &Pubkey,
    accounts: &[AccountInfo],
    decision: bool,
) -> ProgramResult {
    let account_info_iter = &mut accounts.iter();
    let pool_account_info = next_account_info(account_info_iter)?;
    let decider_account_info = next_account_info(account_info_iter)?;
    let clock_info = next_account_info(account_info_iter)?;
    let clock = &Clock::from_account_info(clock_info)?;

    let mut pool = Pool::try_from_slice(&pool_account_info.data.borrow())?;

    if *decider_account_info.key != pool.decider {
        return Err(PoolError::WrongDeciderAccount.into());
    }

    if !decider_account_info.is_signer {
        return Err(PoolError::SignatureMissing.into());
    }

    if pool.decision != Decision::Undecided {
        return Err(PoolError::DecisionAlreadyMade.into());
    }

    let current_slot = clock.slot;
    if current_slot < pool.mint_end_slot || current_slot > pool.decide_end_slot {
        return Err(PoolError::InvalidSlotForDecision.into());
    }

    pool.decision = if decision { Decision::Pass } else { Decision::Fail };
    borsh::to_writer(&mut pool_account_info.data.borrow_mut()[..], &pool)?;
    Ok(())
}

